#!/usr/bin/env python3
import sys, os, re, io, gzip, csv, json, codecs
import xml.etree.ElementTree as ET
from fractions import Fraction
from decimal import Decimal, ROUND_HALF_UP
from datetime import date, datetime, timedelta, timezone

ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
UNITS = {'kg': Fraction(1), 'g': Fraction(1, 1000), 'lb': Fraction(45359237, 10**8),
         'oz': Fraction(28349523125, 10**12)}
MONTHS = {m: i + 1 for i, m in enumerate('jan feb mar apr may jun jul aug sep oct nov dec'.split())}
COLS = {
    'east': {'id', 'type', 'shipped', 'gross', 'net', 'status', 'note'},
    'lakeside': {'id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'},
    'harbor': {'rec', 'ref', 'date', 'weight', 'state'},
    'river': {'t', 'ref', 'shipped', 'weight', 'status'},
    'west': {'id', 'typ', 'shipped', 'weight', 'status', 'note'},
}
DELIM = {'east': ',', 'lakeside': ',', 'harbor': '|', 'river': '\t', 'west': ';'}
BASE_DATE = {'east': 'YMD', 'lakeside': 'ISO', 'harbor': 'ISO', 'river': 'MM/DD/YYYY', 'west': 'DD.MM.YYYY'}
BASE_UNIT = {'east': 'kg', 'lakeside': 'kg', 'harbor': 'kg', 'river': 'kg', 'west': 'kg',
             'central': 'kg', 'north': 'kg'}
STATUS_CODE = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held',
               'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled', 'RET': 'returned',
               'HLD': 'held'}


def read_text(path):
    b = open(path, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8', errors='replace')
    if b[:2] == b'\xff\xfe':
        return b[2:].decode('utf-16-le', errors='replace')
    if b[:2] == b'\xfe\xff':
        return b[2:].decode('utf-16-be', errors='replace')
    enc = 'utf-8'
    head = b[:2048].decode('latin-1')
    m = re.search(r'^#\s*charset\s*:\s*([\w.\-]+)', head, re.I | re.M)
    if m:
        try:
            codecs.lookup(m.group(1))
            enc = m.group(1)
        except LookupError:
            pass
    return b.decode(enc, errors='replace')


def norm_status(s):
    s = (s or '').strip()
    if s.upper() in STATUS_CODE and len(s) <= 3 and s.upper() not in ('DELIVERED',):
        pass
    return re.sub(r'[\s\-]+', '_', s.lower())


def counted(s):
    return s in ('delivered', 'delivered_late')


def to_num(s, decimal_comma=False):
    s = s.strip().replace(' ', '')
    if decimal_comma:
        s = s.replace('.', '').replace(',', '.')
    else:
        s = s.replace(',', '')
    return Fraction(s)


def parse_weight(s, unit, decimal_comma=False):
    """s may carry a unit suffix. returns kg Fraction"""
    s = s.strip()
    m = re.match(r'^([-+]?[\d.,\s]*\d|[-+]?[.,]\d+)\s*([A-Za-z]+)?$', s)
    if not m:
        raise ValueError('weight ' + s)
    u = (m.group(2) or unit or 'kg').lower()
    return to_num(m.group(1), decimal_comma) * UNITS[u]


def serial_date(n):
    return date(1899, 12, 30) + timedelta(days=int(Fraction(n)))


def parse_ship(s, form):
    """return (year, month) in UTC"""
    s = s.strip()
    form = (form or '').upper()
    m = re.match(r'^(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d)(?::(\d\d)(?:[.,]\d+)?)?\s*(Z|[+-]\d\d(?::?\d\d)?)?$', s, re.I)
    if m:
        y, mo, d, hh, mi, ss, tz = m.groups()
        dt = datetime(int(y), int(mo), int(d), int(hh), int(mi), int(ss or 0))
        if tz and tz.upper() != 'Z':
            sign = 1 if tz[0] == '+' else -1
            t = tz[1:].replace(':', '')
            off = timedelta(hours=int(t[:2]), minutes=int(t[2:4] or 0))
            dt = dt - sign * off
        return dt.year, dt.month
    m = re.match(r'^(\d{1,2})\s+([A-Za-z]{3})[A-Za-z]*\.?,?\s+(\d{4})$', s)
    if m:
        return int(m.group(3)), MONTHS[m.group(2).lower()]
    if re.match(r'^\d+(\.\d+)?$', s):
        ip = s.split('.')[0]
        if form == 'SERIAL' or (len(ip) <= 6 and form not in ('YYYYMMDD', 'YYYYDDD')):
            d = serial_date(s)
            return d.year, d.month
        if len(ip) == 8:
            return int(ip[:4]), int(ip[4:6])
        if len(ip) == 7:
            d = date(int(ip[:4]), 1, 1) + timedelta(days=int(ip[4:]) - 1)
            return d.year, d.month
    parts = re.split(r'[-/.]', s)
    if len(parts) == 3 and all(p.isdigit() for p in parts):
        a, b, c = parts
        if len(a) == 4:
            return int(a), int(b)
        if form.startswith('MM/DD') or form == 'MDY':
            return int(c), int(a)
        return int(c), int(b)
    raise ValueError('date ' + s)


def split_id(s):
    m = re.match(r'^\s*SH\D*(\d+)\s*$', s or '', re.I)
    return int(m.group(1)) if m else None


def rtype(s):
    s = (s or '').strip().lower()
    if s.startswith('v'):
        return 'void'
    if s.startswith('c') or s.startswith('a'):
        return 'correction'
    return 'new'


class Rec:
    __slots__ = ('num', 'type', 'ym', 'kg', 'status')


def mk(num, typ, ship, form, wt, status):
    r = Rec()
    r.num = num
    r.type = typ
    r.status = status
    if typ == 'void':
        r.ym = None
        r.kg = None
        return r
    r.ym = parse_ship(ship, form)
    r.kg = wt()
    return r


def logical_lines(text):
    """yield ('comment', line) or ('row', line) handling quoted multi-line fields"""
    buf = None
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if buf is None:
            if line.strip() == '':
                continue
            if line.startswith('#'):
                yield 'comment', line
                continue
            if line.count('"') % 2:
                buf = line
                continue
            yield 'row', line
        else:
            buf += '\n' + line
            if buf.count('"') % 2 == 0:
                yield 'row', buf
                buf = None
    if buf is not None:
        yield 'row', buf


def parse_delimited(depot, text):
    seq = None
    out = []
    cols = COLS[depot]
    delim = DELIM[depot]
    header = None
    date_form = BASE_DATE[depot]
    unit = BASE_UNIT[depot]
    for kind, line in logical_lines(text):
        if kind == 'comment':
            m = re.match(r'^#\s*([^:=]+?)\s*:\s*(.*)$', line)
            if m:
                name = m.group(1).lower()
                val = m.group(2).strip()
                if name == 'seq':
                    try:
                        seq = int(val)
                    except ValueError:
                        pass
                elif name in ('dates', 'date format', 'date', 'date form'):
                    date_form = val.split()[0] if val else date_form
                elif name in ('unit', 'weight unit'):
                    u = val.split()[0].lower() if val else ''
                    if u in UNITS:
                        unit = u
            else:
                m = re.search(r'seq\s*=\s*(\d+)', line)
                if m and seq is None:
                    seq = int(m.group(1))
            continue
        if delim == ',':
            row = next(csv.reader([line], delimiter=','))
        else:
            row = line.split(delim)
        row = [x.strip() if delim != ',' else x for x in row]
        low = [x.strip().lower() for x in row]
        if low and all(x in cols for x in low):
            header = low
            continue
        if header is None:
            header = list(cols) if False else None
            continue
        rowunit = None
        if len(row) == len(header) + 1:
            for i, x in enumerate(row):
                if x.strip().lower() in UNITS:
                    rowunit = x.strip().lower()
                    row = row[:i] + row[i + 1:]
                    break
        if len(row) != len(header):
            continue
        d = dict(zip(header, row))
        idf = d.get('id', d.get('ref'))
        num = split_id(idf)
        if num is None:
            continue
        typ = rtype(d.get('type', d.get('kind', d.get('rec', d.get('t', d.get('typ'))))))
        if depot == 'harbor' and d.get('rec', '').strip().upper().startswith('VOID'):
            typ = 'void'
        st = d.get('status', d.get('state', ''))
        if st.strip().upper() in STATUS_CODE:
            st = STATUS_CODE[st.strip().upper()]
        st = norm_status(st)
        ship = d.get('shipped', d.get('date', ''))
        wraw = d.get('gross', d.get('gross_kg', d.get('weight', '')))
        if depot == 'lakeside':
            wunit = 'kg'
        else:
            wunit = rowunit or unit
        dc = depot == 'west'
        out.append(mk(num, typ, ship, date_form, lambda: parse_weight(wraw, wunit, dc), st))
    return seq, out


def parse_fixed(text):
    seq = None
    out = []
    layout = None
    LEN = {'FW1': 42, 'FW2': 43, 'FW3': 41}
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if '\f' in line or line.strip() == '' and False:
            continue
        if line.startswith('#LAYOUT'):
            layout = line.split()[1].upper()
            continue
        if line.startswith('#SEQ'):
            seq = int(line.split()[1])
            continue
        if line.startswith('#'):
            continue
        if line.strip() == '' or line.startswith('SOUTH'):
            continue
        lay = layout
        for k, v in LEN.items():
            if len(line) == v:
                lay = k
        if lay is None:
            continue
        line = line.ljust(LEN[lay])
        if lay == 'FW1':
            idf, t, sh, w, s = line[0:9], line[9], line[10:17], line[17:25], line[25]
            wf = lambda: Fraction(int(w)) * UNITS['g']
        elif lay == 'FW2':
            t, idf, sh, w, s = line[0], line[1:10], line[10:18], line[18:26], line[26]
            wf = lambda: Fraction(int(w), 100)
        else:
            idf, sh, t, w, s = line[0:9], line[9:16], line[16], line[17:24], line[24]
            wf = lambda: Fraction(int(w), 10) * UNITS['lb']
        num = split_id(idf)
        if num is None:
            continue
        typ = rtype(t)
        st = STATUS_CODE.get(s.strip().upper(), s.strip().lower())
        out.append(mk(num, typ, sh, 'YYYYDDD' if lay != 'FW2' else 'YYYYMMDD', wf, st))
    return seq, out


def local(tag):
    return tag.rsplit('}', 1)[-1]


def parse_xml(text):
    text = re.sub(r'^\s*<\?xml[^>]*\?>', '', text)
    root = ET.fromstring(text)
    seq = None
    try:
        seq = int(root.get('seq'))
    except (TypeError, ValueError):
        pass
    runit = (root.get('weight-unit') or root.get('weight_unit') or 'kg').lower()
    out = []
    for el in root:
        if local(el.tag) != 'shipment':
            continue
        ch = {local(c.tag): c for c in el}
        num = split_id(el.get('id') or (ch['id'].text if 'id' in ch else ''))
        if num is None:
            continue
        typ = rtype(el.get('type') or (ch['type'].text if 'type' in ch else ''))
        st = norm_status(ch['status'].text if 'status' in ch else el.get('status'))
        ship = el.get('shipped') or (ch['shipped'].text if 'shipped' in ch else '')
        w = ch.get('weight')

        def wf(w=w, el=el):
            u = (w.get('unit') or el.get('weight-unit') or runit).lower()
            return parse_weight(w.text, u)
        out.append(mk(num, typ, ship, '', wf, st))
    return seq, out


def parse_json(text):
    seq = None
    out = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        v = json.loads(line)
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and isinstance(o['meta'], dict):
                if 'seq' in o['meta']:
                    seq = int(o['meta']['seq'])
                continue
            num = split_id(str(o.get('id', '')))
            if num is None:
                continue
            typ = rtype(o.get('kind'))
            st = norm_status(o.get('status'))
            wk = [k for k in o if k.lower().startswith('weight')]

            def wf(o=o, wk=wk):
                k = wk[0]
                u = k.lower()[7:] if k.lower().startswith('weight_') else (o.get('unit') or 'kg')
                return parse_weight(str(o[k]), u.lower())
            out.append(mk(num, typ, str(o.get('shipped_at', '')), '', wf, st))
    return seq, out


def parse_file(depot, path):
    text = read_text(path)
    if depot == 'south':
        return parse_fixed(text)
    if depot == 'central':
        return parse_xml(text)
    if depot == 'north':
        return parse_json(text)
    return parse_delimited(depot, text)


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    files = {}
    for f in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, f)
        if os.path.isfile(p):
            files.setdefault(f.split('-')[0].lower(), []).append((f, p))
    corrections = resends = 0
    current = {}
    for depot, fl in files.items():
        exps = []
        for f, p in fl:
            seq, recs = parse_file(depot, p)
            exps.append((seq if seq is not None else -1, f, recs))
        exps.sort(key=lambda e: (e[0], e[1]))
        cur = {}
        for _, _, recs in exps:
            for r in recs:
                if r.type == 'new':
                    if r.num in cur:
                        resends += 1
                    else:
                        cur[r.num] = r
                elif r.type == 'correction':
                    cur[r.num] = r
                    corrections += 1
                else:
                    cur.pop(r.num, None)
                    corrections += 1
        current[depot] = cur
    rank = lambda d: ORDER.index(d) if d in ORDER else len(ORDER)
    owners = {}
    for depot in sorted(current, key=rank):
        for num in current[depot]:
            owners.setdefault(num, []).append(depot)
    handovers = sum(1 for v in owners.values() if len(v) > 1)
    dep = {d: [0, Fraction(0)] for d in sorted(files)}
    mon = {}
    for num, ds in owners.items():
        r = current[ds[0]][num]
        if not counted(r.status):
            continue
        dep[ds[0]][0] += 1
        dep[ds[0]][1] += r.kg
        k = '%04d-%02d' % r.ym
        m = mon.setdefault(k, [0, Fraction(0)])
        m[0] += 1
        m[1] += r.kg

    def rnd(x):
        return float((Decimal(x.numerator) / Decimal(x.denominator)).quantize(Decimal('0.01'), ROUND_HALF_UP)) \
            if False else float(Decimal(x.numerator * 10**6 // x.denominator if False else 0) + _q(x))

    def _q(x):
        scaled = x * 100
        n = scaled.numerator // scaled.denominator
        if (scaled - n) >= Fraction(1, 2):
            n += 1
        return Decimal(n) / 100
    res = {
        'depots': {d: {'shipments': v[0], 'total_kg': float(_q(v[1]))} for d, v in dep.items()},
        'months': {k: {'shipments': mon[k][0], 'total_kg': float(_q(mon[k][1]))} for k in sorted(mon)},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out_file, 'w') as f:
        json.dump(res, f, indent=2)
        f.write('\n')


if __name__ == '__main__':
    main()
